package com.slotix.reservationcore.availability;
import jakarta.validation.*; import org.springframework.http.*; import org.springframework.security.access.prepost.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/companies/{companyId}/resources/{resourceId}/availability-rules") public class AvailabilityRuleController { final AvailabilityRuleService service; public AvailabilityRuleController(AvailabilityRuleService s){service=s;} @GetMapping @PreAuthorize("hasAnyRole('COMPANY_ADMIN','BOOKING_MANAGER','CUSTOMER')") List<AvailabilityRuleResponse> list(@PathVariable UUID companyId,@PathVariable UUID resourceId){return service.list(companyId,resourceId);} @PostMapping @PreAuthorize("hasRole('COMPANY_ADMIN')") ResponseEntity<AvailabilityRuleResponse> create(@PathVariable UUID companyId,@PathVariable UUID resourceId,@Valid @RequestBody CreateAvailabilityRuleRequest q){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(companyId,resourceId,q));}}
